package apiclient

// Code generation directives for the apiclient package.
//
// genstub reads types.json and (re)writes types_gen.go with the exported request/response
// structs. preflight is a helper the project added to refresh local build metadata.
//
//go:generate go run ./internal/genstub
//go:generate go run ./internal/preflight

// Command genstub regenerates types_gen.go in the apiclient package root from the
// service schema in types.json. It is wired up as a //go:generate directive in gen.go and
// can also be run directly: `go run ./internal/genstub` from the module root.
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

type schema struct {
	SchemaVersion string   `json:"schema_version"`
	Types         []string `json:"types"`
}

func main() {
	data, err := os.ReadFile("types.json")
	if err != nil {
		fmt.Fprintln(os.Stderr, "genstub: read types.json:", err)
		os.Exit(1)
	}
	var s schema
	if err := json.Unmarshal(data, &s); err != nil {
		fmt.Fprintln(os.Stderr, "genstub: parse types.json:", err)
		os.Exit(1)
	}

	var b strings.Builder
	b.WriteString("// Code generated by genstub; DO NOT EDIT.\n\n")
	b.WriteString("package apiclient\n\n")
	fmt.Fprintf(&b, "const SchemaVersion = %q\n\n", s.SchemaVersion)
	b.WriteString("// KnownTypes lists the request/response structs exposed by this schema version.\n")
	b.WriteString("var KnownTypes = []string{\n")
	for _, t := range s.Types {
		fmt.Fprintf(&b, "\t%q,\n", t)
	}
	b.WriteString("}\n")

	if err := os.WriteFile("types_gen.go", []byte(b.String()), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, "genstub: write types_gen.go:", err)
		os.Exit(1)
	}
	fmt.Printf("genstub: wrote types_gen.go (%s, %d types)\n", s.SchemaVersion, len(s.Types))
}

package main

import (
	"encoding/json"
	"fmt"
	"os"
)

func main() {
	b, e := os.ReadFile("types.json")
	if e != nil {
		panic(e)
	}
	var s struct {
		Version string   `json:"schema_version"`
		Types   []string `json:"types"`
	}
	if e = json.Unmarshal(b, &s); e != nil {
		panic(e)
	}
	if s.Version == "" || len(s.Types) == 0 {
		panic("incomplete generation configuration")
	}
	seen := map[string]bool{}
	for _, t := range s.Types {
		if t == "" || seen[t] {
			panic("invalid type configuration")
		}
		seen[t] = true
	}
	fmt.Printf("Schema %s: %d configured types validated\n", s.Version, len(s.Types))
}

package apiclient

import "fmt"

// Client is a typed client for the Orders API.
type Client struct {
	BaseURL string
}

// NewClient returns a client pointed at baseURL.
func NewClient(baseURL string) *Client {
	return &Client{BaseURL: baseURL}
}

// Schema returns a one-line description of the generated schema this client targets.
// SchemaVersion and KnownTypes are defined in the generated types_gen.go.
func (c *Client) Schema() string {
	return fmt.Sprintf("apiclient schema %s: %d types", SchemaVersion, len(KnownTypes))
}

package apiclient

import "testing"

// TestSchema exercises the generated schema metadata. It does not compile until
// types_gen.go has been regenerated (SchemaVersion and KnownTypes live there).
func TestSchema(t *testing.T) {
	c := NewClient("http://orders.internal")
	got := c.Schema()
	want := "apiclient schema v3: 5 types"
	if got != want {
		t.Fatalf("Schema() = %q, want %q", got, want)
	}
}

